output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts should not be taken into single-file shelf aisles where shelves flank the shopper on both sides.",
    "abstraction": {
      "state_properties": {
        "horizontal_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "vertical_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "two_sided_single_file_shelf_aisle": {
          "or": [
            "horizontal_single_file_between_shelves",
            "vertical_single_file_between_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "two_sided_single_file_shelf_aisle"
        ]
      }
    },
    "justification": "The rule is defined by local clearance and shelf adjacency rather than coordinates, so it applies to any store with narrow shelf aisles."
  },
  {
    "id": "no_enter_single_file_aisle_with_cart",
    "text": "A shopper must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "horizontal_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "vertical_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "two_sided_single_file_shelf_aisle": {
          "or": [
            "horizontal_single_file_between_shelves",
            "vertical_single_file_between_shelves"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "two_sided_single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    },
    "justification": "It refers to entering a locally defined narrow shelf aisle, not to a named aisle or cell in a particular map."
  },
  {
    "id": "no_cart_item_interaction_in_single_file_aisle",
    "text": "Items in single-file shelf aisles should be taken without bringing the cart alongside the shelf.",
    "abstraction": {
      "state_properties": {
        "horizontal_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "vertical_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "two_sided_single_file_shelf_aisle": {
          "or": [
            "horizontal_single_file_between_shelves",
            "vertical_single_file_between_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "two_sided_single_file_shelf_aisle",
          "hasCart",
          "INTERACT"
        ]
      }
    },
    "justification": "The distinction is based on whether the shelf is served from a single-file aisle, a layout-independent property."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or lets go of a cart, they are obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "retrieve_cart"
    },
    "justification": "Parking and retrieving a cart are defined by changes in cart possession, so the rule is meaningful in any store layout."
  },
  {
    "id": "park_cart_only_in_open_passing_space",
    "text": "A cart may be parked only in an open passing space, not beside shelves or in constricted areas.",
    "abstraction": {
      "state_properties": {
        "open_passing_space": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "open_passing_space"
          }
        ]
      }
    },
    "justification": "Open passing space is characterized by local width and absence of adjacent shelves rather than by store-specific parking coordinates."
  },
  {
    "id": "use_cart_at_accessible_shelves",
    "text": "When a shelf is reachable from a cart-accessible aisle, the shopper should interact with it while keeping the cart.",
    "abstraction": {
      "state_properties": {
        "horizontal_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "vertical_single_file_between_shelves": {
          "and": [
            {
              "le": [
                "freeWidthV",
                1
              ]
            },
            "shelfN",
            "shelfS"
          ]
        },
        "two_sided_single_file_shelf_aisle": {
          "or": [
            "horizontal_single_file_between_shelves",
            "vertical_single_file_between_shelves"
          ]
        },
        "cart_accessible_shelf_area": {
          "and": [
            "adjShelf",
            {
              "not": "two_sided_single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_accessible_shelf_area",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule separates cart-accessible shelf fronts from single-file shelf aisles using only local geometry."
  },
  {
    "id": "must_get_cart",
    "text": "A shopper is obliged to acquire a cart during the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The rule concerns cart possession, a store-independent shopping-domain feature, and does not rely on where carts are located."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper must not exit the store without the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The constraint is expressed in terms of the exit action and cart possession, so it generalizes across different floor plans."
  }
]
